dashboard.definition:
{
  "title": "Wazuh - Docker - Overview dashboard",
  "description": "Docker - Overview dashboard of the Wazuh dashboard, on the findings exported from the Wazuh indexer.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_01": {
      "type": "ds.search",
      "name": "Top 5 images",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"docker\" | eval f1='container.image.name' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"container.image.name\", metric as \"Count\""
      }
    },
    "ds_02": {
      "type": "ds.search",
      "name": "Top 5 events",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"docker\" | eval f1='event.action' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"event.action\", metric as \"Count\""
      }
    },
    "ds_03": {
      "type": "ds.search",
      "name": "Events by source over time",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"docker\" | eval f1='event.category{}' | timechart useother=f usenull=f limit=5 count by f1"
      }
    },
    "ds_04": {
      "type": "ds.search",
      "name": "viz_04",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"docker\" | eval f1='wazuh.agent.name', f2='container.image.name', f3='event.action', f4='event.category{}', f5='container.name' | bin _time bins=24 | stats count as metric by _time, f1, f2, f3, f4, f5 | sort - metric | head 500 | rename f1 as \"wazuh.agent.name\", f2 as \"container.image.name\", f3 as \"event.action\", f4 as \"event.category\", f5 as \"container.name\", metric as \"Count\""
      }
    }
  },
  "visualizations": {
    "viz_01": {
      "type": "splunk.pie",
      "title": "Top 5 images",
      "dataSources": {
        "primary": "ds_01"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_02": {
      "type": "splunk.pie",
      "title": "Top 5 events",
      "dataSources": {
        "primary": "ds_02"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_03": {
      "type": "splunk.column",
      "title": "Events by source over time",
      "dataSources": {
        "primary": "ds_03"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_04": {
      "type": "splunk.table",
      "title": "",
      "dataSources": {
        "primary": "ds_04"
      },
      "options": {}
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1200,
      "height": 576,
      "display": "auto-scale"
    },
    "globalInputs": [
      "input_global_trp"
    ],
    "structure": [
      {
        "item": "viz_01",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 396,
          "h": 196
        }
      },
      {
        "item": "viz_02",
        "type": "block",
        "position": {
          "x": 400,
          "y": 0,
          "w": 396,
          "h": 196
        }
      },
      {
        "item": "viz_03",
        "type": "block",
        "position": {
          "x": 800,
          "y": 0,
          "w": 396,
          "h": 196
        }
      },
      {
        "item": "viz_04",
        "type": "block",
        "position": {
          "x": 0,
          "y": 200,
          "w": 1196,
          "h": 356
        }
      }
    ]
  }
}
